import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPO = ROOT / "zoo"
PINS = {'zoo_keeper/recipes/traffic_signal.py': 'be9413b5757ea9e5', 'zoo_keeper/genome/species/traffic_signal.json': '2f7fcb1c26ff1bcb'}
EDITS = {'zoo_keeper/recipes/traffic_signal.py': [('lines 21-22', 'under an arm.\n"""\n', 'under an arm.\n\nTWO HANDS (1.121.0). The heads face -y off an arm along +x: seen from above,\nthe face is the arm turned clockwise, which is a pole on the driver\'s LEFT\nreaching right over the lanes. The `right` form turns both heads round to\nface +y -- the arm turned counter-clockwise -- for the pole a US junction\nstands on the approach\'s far RIGHT corner, its arm back over the lanes and\nits heads facing the driver (MUTCD 4D.14: two faces at least 8 ft apart, one\nat least 40 ft beyond the stop line; the arm\'s head and the pole\'s are 4.3 m\napart). The walker, walking cold run 9386: "where are the traffic lights for\nthis side of the road?" -- Lot stood a signal only on a junction\'s yielding\nleg, its heads facing across it. Same geometry, materials and collision\neither way; only the heads, their lenses and visors change side.\n"""\n'), ('lines 42-45', 'def _head(bm, lens_bms, centre):\n    """A three-lens head hung with its top at ``centre``, facing -y.\n    ``lens_bms`` holds one bmesh per lens row -- red, amber, green -- so each\n    row can wear its own colour."""\n', 'def _head(bm, lens_bms, centre, face=-1):\n    """A three-lens head hung with its top at ``centre``, facing -y (``face``\n    -1) or +y (+1, the `right` form). ``lens_bms`` holds one bmesh per lens\n    row -- red, amber, green -- so each row can wear its own colour."""\n'), ('lines 50-50', '        y = cy - (HEAD_D / 2.0 + 0.012)\n', '        y = cy + face * (HEAD_D / 2.0 + 0.012)\n'), ('lines 53-53', '        geometry.add_box(bm, (cx, y - 0.055, lz + LENS_R * 0.8),\n', '        geometry.add_box(bm, (cx, y + face * 0.055, lz + LENS_R * 0.8),\n'), ('lines 76-77', '\n    mast = w * 0.62                      # the signal arm, over the road\n', '\n    # which way the heads face: -y, or +y on the `right` form (TWO HANDS)\n    face = 1 if (plan.get("params") or {}).get("form") == "right" else -1\n    mast = w * 0.62                      # the signal arm, over the road\n'), ('lines 98-99', '    _head(bm, lens_bms, (mast * 0.92, 0.0, arm_z - 0.08))      # over the road\n    _head(bm, lens_bms, (POLE_D * 1.4, 0.0, arm_z - 0.60))     # the near head\n', '    _head(bm, lens_bms, (mast * 0.92, 0.0, arm_z - 0.08), face)      # over the road\n    _head(bm, lens_bms, (POLE_D * 1.4, 0.0, arm_z - 0.60), face)     # the near head\n')], 'zoo_keeper/genome/species/traffic_signal.json': [('lines 26-26', '  "params": {},\n', '  "params": {\n    "form": [\n      "auto",\n      "right"\n    ]\n  },\n')]}
NEW_FILES = {'tests/test_signal_hand.py': '"""A traffic signal for the driver\'s right (1.121.0). The walker, walking cold run 9386: "where are the traffic lights\nfor this side of the road?" -- Lot stood a signal only on a junction\'s yielding leg. The heads face -y off an arm along\n+x, which is a pole on the driver\'s LEFT; the `right` form faces them +y, for the pole on an approach\'s far right\ncorner with its arm back over the lanes.\n\nThe kit half runs anywhere. The bpy half skips without Blender and was run inside Blender 5.1.1 for this change, from\nthe repo root:\n\n    blender -b --factory-startup --python-expr "import sys, pytest; sys.path.insert(0, \'.\'); print(\'rc\', int(pytest.main([\'-q\', \'-p\', \'no:cacheprovider\', \'tests/test_signal_hand.py\'])))"\n"""\nfrom __future__ import annotations\n\nimport pytest\n\nfrom zoo_keeper.core import genome, kit\n\n\ndef _slot(form=None):\n    s = {"slot_id": "sig", "role": "prop", "size_mod": "full", "style": 1, "species": "traffic_signal",\n         "fit": {"dims": [8.0, 0.62, 6.5], "pivot": "center"}}\n    if form:\n        s["form"] = form\n    return s\n\n\ndef test_the_genome_lists_the_right_form():\n    assert genome.load_species("traffic_signal")["params"]["form"] == ["auto", "right"]\n\n\ndef test_the_kit_builds_the_right_form_under_its_own_name():\n    plan = kit.plan_kit({"building_id": "t", "slots": [_slot("right"), _slot()]}, theme="delco_1997", style=1)\n    assert plan["dressing_fallbacks"] == []\n    stems = sorted(m["stem"] for m in plan["modules"])\n    assert len(stems) == 2 and stems[0] != stems[1]\n    assert any(s.endswith("_fright") for s in stems), stems\n\n\ndef test_a_hand_the_genome_does_not_list_is_dropped_and_said():\n    got, why = kit.honour_dressing({"form": "left"}, "traffic_signal")\n    assert got == {"form": None, "stock": None, "variant": None} and why\n\n\n@pytest.mark.parametrize("form,side", [(None, -1), ("right", 1)])\ndef test_bpy_the_heads_face_minus_y_or_on_the_right_form_plus_y(form, side, tmp_path):\n    pytest.importorskip("bpy")\n    import bpy\n    from zoo_keeper.bpylayer import build as B\n    for o in list(bpy.data.objects):\n        bpy.data.objects.remove(o, do_unlink=True)\n    plan = kit.plan_kit({"building_id": "t", "slots": [_slot(form)]}, theme="delco_1997", style=1)\n    B.build_module(plan["modules"][0], str(tmp_path / "out"), theme="delco_1997", style=1,\n                   options={"save_blend": False})\n    lenses = [o for o in bpy.data.objects if o.type == "MESH" and "TrafficSignal_Lens" in o.name]\n    assert len(lenses) == 3, [o.name for o in bpy.data.objects]\n    for o in lenses:\n        ys = [(o.matrix_world @ v.co).y for v in o.data.vertices]\n        assert ys and all(y * side > 0 for y in ys), (o.name, min(ys), max(ys))\n'}
CHANGELOG = '## [1.121.0] - a traffic signal for the driver\'s right\n\n**The walker, walking cold run 9386** (the factory\'s `docs/findings/walk_2026-10-23_9386/`, finding 12): "where are\nthe traffic lights for this side of the road?" The signal\'s heads face -y off an arm along +x -- from above, the face\nis the arm turned clockwise, which is a pole on the driver\'s LEFT reaching right over the lanes. A US junction stands\nits signal on an approach\'s far RIGHT corner, arm back over the lanes, heads facing the driver (MUTCD 4D.14: two\nfaces at least 8 ft apart, one at least 40 ft beyond the stop line). Lot cannot turn the left-hand module into that:\nit is a mirror, and a negative scale would mirror the pole\'s collider with it.\n\n### Added\n- **`traffic_signal`\'s `right` form**: both heads, their lenses and visors face +y -- the arm turned\n  counter-clockwise. The genome lists `params.form: ["auto", "right"]`, so `kit.honour_dressing` keeps it and the\n  module is `..._fright`; same geometry, materials, collision and triangles either way. Lot 0.128.0 asks for it.\n\n### Tests\n- `tests/test_signal_hand.py` (new): the genome lists the form; the kit builds it under its own name and drops a hand\n  it does not list; in Blender 5.1.1, every lens vertex of the plain module at -y and of the `right` form at +y. The\n  form\'s tests fail on 1.120.1, the Blender one on behaviour.\n\n'
OLD_VERSION, NEW_VERSION = '1.120.1', '1.121.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: zoo/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: zoo/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: zoo/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: zoo/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Zoo %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in zoo/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
